    is_customer_waiting BOOLEAN,
    is_orig_waiter BOOLEAN,
    is_sold_by_dealer BOOLEAN,
    is_special_customer BOOLEAN,
    block_auto_msg BOOLEAN,
    comments VARCHAR(255),
    remarks VARCHAR(255),
    contact_email_address VARCHAR(120),
    contact_phone_number VARCHAR(20),
    purchase_order_number VARCHAR(20),
    priority_value NUMBER(38,0),
